// items = [moldura, recorte PNG com fundo transparente por cima da moldura]
const [frame, cutout] = items;
tl.fromTo(frame, { scale: 0.9, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.4, ease: "power3.out" }, t);
tl.fromTo(cutout, { y: 120, scale: 0.95, clipPath: "inset(0% 0% 30% 0%)" }, { y: -60, scale: 1.05, clipPath: "inset(-50% -50% 0% -50%)", duration: 0.6, ease: "back.out(1.6)" }, t + 0.25);

// items = fotos já posicionadas; rotações finais fixas
const rot = [-6, 4, -3, 8, -8, 2];
tl.fromTo(items, { scale: 1.3, opacity: 0, rotation: (i) => rot[i % rot.length] * 2 }, { scale: 1, opacity: 1, rotation: (i) => rot[i % rot.length], duration: 0.45, ease: "back.out(1.5)", stagger: 0.1 }, t);

const sceneDur = 4; // duração da cena em s (troque pela real)

// el = grupo com as cópias aninhadas, cada uma 70% da anterior (scale 0.7^i no CSS)
tl.fromTo(el, { scale: 1 }, { scale: 1 / 0.7, duration: 1.5, ease: "none", repeat: Math.max(0, Math.floor(sceneDur / 1.5) - 1) }, t);

const sceneDur = 4; // duração da cena em s (troque pela real)

// el = grupo de 8 fatias (rotate(i*45deg), ímpares com scaleX(-1), clip-path triangular); items = imagem dentro de cada fatia
tl.fromTo(items, { rotation: 0, scale: 1.2 }, { rotation: 90, scale: 1.4, duration: sceneDur, ease: "none" }, t);
tl.fromTo(el, { rotation: 0 }, { rotation: -30, duration: sceneDur, ease: "sine.inOut" }, t);

// items = [original, cópia espelhada]; o clip local é igual nos dois, a inversão faz a cópia abrir para a direita
const [orig, copy] = items;
tl.fromTo(orig, { clipPath: "inset(0% 50% 0% 50%)" }, { clipPath: "inset(0% 50% 0% 0%)", duration: 0.7, ease: "power3.out" }, t);
tl.fromTo(copy, { scaleX: -1, clipPath: "inset(0% 50% 0% 50%)" }, { scaleX: -1, clipPath: "inset(0% 50% 0% 0%)", duration: 0.7, ease: "power3.out" }, t);

// items = [moldura branca da polaroid, foto dentro dela]
const [frame, photo] = items;
tl.fromTo(frame, { y: -900, rotation: -25 }, { y: 0, rotation: -4, duration: 0.6, ease: "power3.out" }, t);
tl.fromTo(photo, { filter: "brightness(3) saturate(0) contrast(0.6)" }, { filter: "brightness(1) saturate(1) contrast(1)", duration: 1.2, ease: "power1.inOut" }, t + 0.4);

// estrela de 5 pontas como polygon; 0.5625 = 1080/1920 corrige a proporção vertical
const star = (s) => "polygon(" + Array.from({ length: 10 }, (_, i) => {
  const ang = -Math.PI / 2 + i * Math.PI / 5, rr = (i % 2 ? 0.45 : 1) * s;
  return (50 + Math.cos(ang) * rr).toFixed(2) + "% " + (50 + Math.sin(ang) * rr * 0.5625).toFixed(2) + "%";
}).join(", ") + ")";
tl.fromTo(el, { clipPath: star(0) }, { clipPath: star(45), duration: 0.8, ease: "power3.inOut" }, t);

// items = [metade de cima, metade de baixo, divisória]
const [upper, lower, line] = items;
tl.fromTo(upper, { yPercent: -100 }, { yPercent: 0, duration: 0.6, ease: "power3.out" }, t);
tl.fromTo(lower, { yPercent: 100 }, { yPercent: 0, duration: 0.6, ease: "power3.out" }, t + 0.08);
tl.fromTo(line, { scaleX: 0 }, { scaleX: 1, duration: 0.4, ease: "power2.inOut" }, t + 0.4);

// el = círculo transparente com box-shadow: 0 0 0 4000px rgba(0,0,0,0.72) (o escuro é a sombra)
tl.fromTo(el, { scale: 4, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.6, ease: "power3.out" }, t);
// anda até o segundo alvo
tl.fromTo(el, { x: 0, y: 0 }, { x: 220, y: -340, duration: 0.6, ease: "power3.inOut", immediateRender: false }, t + 1.0);

// items = [adesivo, sombra do adesivo]
const [sticker, shadow] = items;
tl.fromTo(sticker, { scale: 1.4, rotation: 18, opacity: 0 }, { scale: 1, rotation: -6, opacity: 1, duration: 0.3, ease: "back.out(2)" }, t);
tl.fromTo(shadow, { scale: 1.5, opacity: 0 }, { scale: 1, opacity: 0.35, duration: 0.3, ease: "power2.out" }, t);
// ponta dobrada desce e o adesivo fica inteiro
tl.fromTo(sticker, { clipPath: "polygon(0% 0%, 100% 0%, 100% 78%, 78% 100%, 0% 100%)" }, { clipPath: "polygon(0% 0%, 100% 0%, 100% 100%, 100% 100%, 0% 100%)", duration: 0.2, ease: "power2.out" }, t + 0.25);

const sceneDur = 4; // duração da cena em s (troque pela real)

// items = [palavra (wrapper com mask-image do texto), vídeo dentro dele]
const [word, video] = items;
tl.fromTo(word, { scale: 1.2, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.7, ease: "power3.out" }, t);
tl.fromTo(video, { yPercent: -8 }, { yPercent: 8, duration: sceneDur, ease: "none" }, t);
